import hashlib,json,pathlib,sys
rows=[]
for name in sys.argv[1:]:
 data=pathlib.Path(name).read_bytes()
 try:
  compile(data.decode('utf-8-sig'),name,'exec')
  result={'status':'passed','error':None}
 except Exception as error:
  result={'status':'failed','error':repr(error)}
 rows.append({'path':name,'bytes':len(data),'sha256':hashlib.sha256(data).hexdigest(),**result})
print(json.dumps({'files':rows,'passed':sum(row['status']=='passed' for row in rows),'failed':sum(row['status']=='failed' for row in rows)},ensure_ascii=False))
sys.exit(int(any(row['status']=='failed' for row in rows)))
